def jump_dp(a):
    n=len(a); dp=[10**9]*n; dp[0]=0
    for i in range(n):
        for j in range(1, a[i]+1):
            if i+j < n: dp[i+j]=min(dp[i+j], dp[i]+1)
    return dp[-1]

def jump(a):
    jumps=end=far=0
    for i in range(len(a)-1):
        far=max(far, i+a[i])
        if i==end:
            jumps+=1; end=far
    return jumps
